uint16_t naShuffledIndex(uint16_t position) {
  if (position < 130) {
    return position;
  }
  if (position < 278) {
    return 130 + ((73 * (position - 130) + 17) % 148);
  }
  if (position < 505) {
    return 278 + ((101 * (position - 278) + 29) % 227);
  }
  return position; // Imported IRDB power codes appended after existing database
}



